/* --- combatPanelShared.js --- */
// js/combatPanelShared.js
// 🧩 共用戰鬥面板渲染器
//
// 目的：讓「一般戰鬥 / 打圖戰鬥 / 礦坑戰鬥」三個面板使用同一套視覺樣板：
//   ATB 條（含名字、戰力、百分比）→ HP/MP 條 → 下一招預告 → 門派特色表 → 屬性行
//
// 各系統只需呼叫：
//   HY.CombatPanel.unitHtml(opts)   → 單一戰位 HTML
//   HY.CombatPanel.css()            → 共用樣式字串
//   HY.CombatPanel.nextActionHtml() → 下一招預告
window.HY = window.HY || {};
(function () {
    'use strict';

    function esc(s) {
        return String(s == null ? '' : s)
            .replace(/&/g, '&amp;').replace(/</g, '&lt;')
            .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    }
    function num(v, d) { return (typeof v === 'number' && isFinite(v)) ? v : (d || 0); }
    function fmt(n) { return Math.floor(num(n, 0)).toLocaleString(); }

    /** 共用 CSS（class 前缀 cp-，避免與各面板原有樣式衝突） */
    function css() {
        return [
            /* 戰位容器 */
            '.cp-slot{background:#121822;border-radius:4px;padding:5px 7px;display:flex;',
            'flex-direction:column;gap:2px;cursor:pointer;border-left:3px solid #10b981;',
            'transition:opacity .18s,border-color .15s,background .12s;margin-bottom:5px;}',
            '.cp-slot.main{border-left-color:#00e5ff;}',
            '.cp-slot:hover{background:#16202c;border-left-color:#38bdf8;}',
            '.cp-slot.dead{opacity:.45;}',
            '.cp-slot.empty{border-left-color:#1e293b;opacity:.45;cursor:default;}',
            '.cp-slot.enemy{border-left-color:#ef4444;background:#151016;}',
            '.cp-slot.enemy:hover{background:#1f1418;}',
            /* ATB 條 */
            '.cp-uh{position:relative;height:22px;border-radius:3px;overflow:hidden;',
            'border:1px solid #78350f;background:#060a12;flex-shrink:0;box-sizing:border-box;}',
            '.cp-uh .cp-fill{position:absolute;top:0;left:0;bottom:0;',
            'background:linear-gradient(90deg,#78350f,#c89d54 55%,#f0c674);',
            'transition:width .18s linear;}',
            '.cp-uh.full{border-color:#f0c674;box-shadow:0 0 8px rgba(240,198,116,.6);}',
            '.cp-uh.full .cp-fill{background:linear-gradient(90deg,#c89d54,#fde68a);}',
            '.cp-uh .cp-tx{position:absolute;inset:0;display:flex;align-items:center;gap:5px;',
            'padding:0 6px;font-size:.72rem;font-weight:bold;color:#fff;',
            'text-shadow:0 1px 2px #000,0 0 4px rgba(0,0,0,.85);white-space:nowrap;}',
            '.cp-uh .cp-nm{flex:1 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;}',
            /* ⭐ v497：等級徽章（在戰力之前，藍色系以區別於金色的戰力） */
            '.cp-uh .cp-lv{flex:0 0 auto;padding:0 4px;border-radius:2px;',
            'background:rgba(15,32,54,.78);border:1px solid rgba(125,211,252,.55);',
            'color:#7dd3fc;font-size:.68rem;}',
            '.cp-uh.enemy .cp-lv{background:rgba(45,20,24,.78);',
            'border-color:rgba(252,165,165,.5);color:#fca5a5;}',
            '.cp-uh .cp-pw{flex:0 0 auto;padding:0 4px;border-radius:2px;background:rgba(0,0,0,.55);',
            'color:#fbbf24;font-size:.68rem;}',
            '.cp-uh .cp-pc{flex:0 0 auto;color:#e2e8f0;font-size:.7rem;}',
            /* ⭐ 敵方集氣條與我方同色（使用者要求）——移除獨立的紅色樣式，
               沿用上方共用的金色漸層與滿氣發光。 */
            /* HP / MP */
            '.cp-hp,.cp-mp{position:relative;height:18px;border-radius:3px;overflow:hidden;',
            'border:1px solid #334155;background:#090d14;flex-shrink:0;box-sizing:border-box;}',
            '.cp-hp .cp-fi,.cp-mp .cp-fi{position:absolute;top:0;left:0;bottom:0;',
            'transition:width .18s linear;}',
            '.cp-hp .cp-fi{background:linear-gradient(90deg,#7f1d1d,#dc2626 45%,#f87171);}',
            '.cp-mp .cp-fi{background:linear-gradient(90deg,#1e3a8a,#2563eb 45%,#60a5fa);}',
            '.cp-hp.enemy .cp-fi{background:linear-gradient(90deg,#450a0a,#b91c1c 45%,#ef4444);}',
            /* ⭐ v57：能量護盾條（青藍色） */
            '.cp-es{position:relative;height:18px;border-radius:3px;overflow:hidden;',
            'border:1px solid #0369a1;background:#090d14;flex-shrink:0;box-sizing:border-box;',
            'box-shadow:0 0 5px rgba(56,189,248,.35);}',
            '.cp-es .cp-fi{position:absolute;top:0;left:0;bottom:0;transition:width .18s linear;',
            'background:linear-gradient(90deg,#075985,#0ea5e9 45%,#7dd3fc);}',
            '.cp-es.enemy .cp-fi{background:linear-gradient(90deg,#164e63,#0891b2 45%,#67e8f9);}',
            '.cp-es .cp-tx{position:absolute;inset:0;display:flex;align-items:center;',
            'justify-content:center;font-size:.68rem;font-weight:bold;color:#fff;',
            'text-shadow:0 1px 2px #000,0 0 4px rgba(0,0,0,.85);letter-spacing:.2px;',
            'pointer-events:none;white-space:nowrap;line-height:1;}',
            '.cp-hp .cp-tx,.cp-mp .cp-tx{position:absolute;inset:0;display:flex;align-items:center;',
            'justify-content:center;font-size:.68rem;font-weight:bold;color:#fff;',
            'text-shadow:0 1px 2px #000,0 0 4px rgba(0,0,0,.85);letter-spacing:.2px;',
            'pointer-events:none;white-space:nowrap;line-height:1;}',
            /* 資訊行 */
            '.cp-line{height:16px;line-height:16px;background:rgba(0,0,0,.45);padding:0 5px;',
            'font-size:.69rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;',
            'border-radius:2px;box-sizing:border-box;flex-shrink:0;color:#94a3b8;}',
            /* 門派特色表 */
            '.cp-feat{display:grid;grid-template-columns:auto 1fr;gap:.5px 5px;',
            'background:rgba(0,0,0,.40);border-radius:3px;padding:2px 5px;font-size:.66rem;',
            'line-height:1.15;border-left:2px solid #334155;box-sizing:border-box;flex-shrink:0;}',
            '.cp-feat .cp-fk{color:#94a3b8;white-space:nowrap;}',
            '.cp-feat .cp-fv{color:#e2e8f0;font-weight:bold;white-space:nowrap;overflow:hidden;',
            'text-overflow:ellipsis;justify-self:end;}',
            '.cp-feat .cp-fv.hl{color:#fbbf24;}',
            /* 下一招預告 */
            '.cp-next{display:flex;align-items:center;gap:4px;height:17px;line-height:17px;',
            'padding:0 6px;font-size:.70rem;white-space:nowrap;overflow:hidden;border-radius:2px;',
            'box-sizing:border-box;flex-shrink:0;background:rgba(0,0,0,.50);border-left:2px solid #475569;}',
            '.cp-next .cp-ni{flex:0 0 auto;font-size:.72rem;}',
            '.cp-next .cp-ns{flex:0 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;font-weight:bold;}',
            '.cp-next .cp-na{flex:0 0 auto;color:#475569;font-size:.66rem;}',
            '.cp-next .cp-nt{flex:0 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;font-weight:bold;}',
            '.cp-next.k-heal{border-left-color:#10b981;background:rgba(16,185,129,.12);}',
            '.cp-next.k-heal .cp-ns,.cp-next.k-heal .cp-nt{color:#6ee7b7;}',
            '.cp-next.k-attack{border-left-color:#ef4444;background:rgba(239,68,68,.12);}',
            '.cp-next.k-attack .cp-ns,.cp-next.k-attack .cp-nt{color:#fca5a5;}',
            '.cp-next.k-support{border-left-color:#38bdf8;background:rgba(56,189,248,.12);}',
            '.cp-next.k-support .cp-ns,.cp-next.k-support .cp-nt{color:#7dd3fc;}',
            '.cp-next.k-item{border-left-color:#a855f7;background:rgba(168,85,247,.14);}',
            '.cp-next.k-item .cp-ns,.cp-next.k-item .cp-nt{color:#c084fc;}',
            '.cp-next.k-revive{border-left-color:#fbbf24;background:rgba(251,191,36,.16);}',
            '.cp-next.k-revive .cp-ns,.cp-next.k-revive .cp-nt{color:#fde68a;}',
            '.cp-next.k-idle{border-left-color:#334155;background:rgba(0,0,0,.35);}',
            '.cp-next.k-idle .cp-ns,.cp-next.k-idle .cp-nt{color:#475569;}',
            '.cp-next.k-dead{border-left-color:#7f1d1d;background:rgba(127,29,29,.18);opacity:.6;}',
            '.cp-next.k-dead .cp-ns,.cp-next.k-dead .cp-nt{color:#991b1b;text-decoration:line-through;}'
        ].join('');
    }

    /** HP/MP 條 */
    function barHtml(kind, cur, max, isEnemy, idPrefix) {
        var safeMax = Math.max(0, num(max, 0));
        var safeCur = Math.max(0, Math.min(num(cur, 0), safeMax));
        var pct = safeMax > 0 ? (safeCur / safeMax) * 100 : 0;
        var isHp = kind === 'hp';
        var cls = isHp ? ('cp-hp' + (isEnemy ? ' enemy' : '')) : 'cp-mp';
        var icon = isHp ? '❤ ' : '💧 ';
        var idAttr = idPrefix ? ' id="' + idPrefix + '"' : '';
        var txId = idPrefix ? ' id="' + idPrefix + '-tx"' : '';
        return '<div class="' + cls + '"' + idAttr + '>' +
            '<div class="cp-fi" style="width:' + pct.toFixed(1) + '%"></div>' +
            '<div class="cp-tx"' + txId + '>' + icon + fmt(safeCur) + ' / ' + fmt(safeMax) + '</div>' +
            '</div>';
    }

    /** ⭐ v57：能量護盾條
        ⭐⭐⭐ v482：罡氣／護盾機制已完整移除 → 一律回傳空字串。
        （保留函式簽章，避免 3 處呼叫端報錯） */
    function esBarHtml(cur, max, isEnemy, idPrefix) {
        return '';
    }

    /** ATB 條
        ⚠️ name 允許傳入已轉義的 HTML（因為戰位標題常帶徽章），
           由呼叫端決定是否含標籤。
        ⭐ v508：avatarHtml —— 可選的小頭像（怪物立繪 / 角色立繪） */
    function atbHtml(name, power, pct, isEnemy, idPrefix, levelText, avatarHtml) {
        var p = Math.max(0, Math.min(100, Math.floor(num(pct, 0))));
        var cls = 'cp-uh' + (isEnemy ? ' enemy' : '') + (p >= 100 ? ' full' : '');
        var idAttr = idPrefix ? ' id="' + idPrefix + '"' : '';
        var nameHtml = String(name == null ? '' : name);
        return '<div class="' + cls + '"' + idAttr + '>' +
            '<div class="cp-fill" style="width:' + p.toFixed(1) + '%"></div>' +
            '<div class="cp-tx">' +
            '<span class="cp-nm">' + (avatarHtml || '') + nameHtml + '</span>' +
            /* ⭐ v497：等級徽章（在戰力之前） */
            (levelText ? '<span class="cp-lv">' + esc(levelText) + '</span>' : '') +
            (power ? '<span class="cp-pw">⚔️' + esc(power) + '</span>' : '') +
            '<span class="cp-pc">' + (p >= 100 ? '⚡ 滿' : '⚡ ' + p + '%') + '</span>' +
            '</div></div>';
    }

    /** 門派特色表 */
    function featHtml(member) {
        var g = window.HY.game || {};
        var featSys = g.sectFeatSys;
        var Data = window.HY.Data || {};
        if (!featSys || !member || !member.sect ||
            typeof featSys.getStatusTable !== 'function') {
            return '';
        }
        var table = null;
        try { table = featSys.getStatusTable(member); } catch (e) { table = null; }
        if (!table || !table.rows || !table.rows.length) return '';
        var rows = table.rows.map(function (r) {
            return '<span class="cp-fk">' + esc(r.k) + '</span>' +
                '<span class="cp-fv' + (r.hl ? ' hl' : '') + '">' + esc(r.v) + '</span>';
        }).join('');
        return '<div class="cp-feat" style="border-left-color:' + esc(table.color || '#334155') + '">' +
            '<span class="cp-fk" style="color:' + esc(table.color || '#94a3b8') + ';font-weight:bold">' +
            esc((table.icon || '') + ' ' + (table.name || '')) + '</span><span class="cp-fv"></span>' +
            rows + '</div>';
    }

    /** ⭐ 礦坑戰鬥的下一招預測（完全使用 delveBattle 的資料）
        · 我方：取主控角色的招式池最強招，目標為當前礦坑敵人
        · 敵方：取技能池最強招，目標為「鎖定」的隊員（不會每幀亂跳） */
    function _previewDelveAction(unit, isEnemy) {
        if (!unit) return null;
        var g = window.HY.game || {};
        var db = g.delveBattle;
        var Data = window.HY.Data || {};
        var ARTS = Data.MARTIAL_ARTS || {};
        var charSys = g.charSys;
        if (!charSys) return null;

        /* 已陣亡 */
        if (num(unit.currentHp, 0) <= 0) {
            return {
                skillName: '已陣亡', kind: 'dead', targetName: '—',
                aoe: false, targetIsBoss: false
            };
        }

        if (isEnemy) {
            /* 敵方：技能池取倍率最高的一招 */
            var list = (unit.skills || []).filter(function (s) { return s && s.name; });
            var pick = list.length ? list.slice().sort(function (a, b) {
                return num(b.mult, 1) - num(a.mult, 1);
            })[0] : null;

            /* ⭐ 目標必須「鎖定」，否則每次重繪都會亂跳。
               優先沿用 unit._lockedTargetId，沒有才挑一個並記住。 */
            var members = (g.partySys ? g.partySys.getPartyMembers() : [])
                .filter(function (m) { return m && num(m.currentHp, 0) > 0; });
            var tgt = null;
            var locked = unit._lockedTargetId;
            if (locked) {
                for (var i = 0; i < members.length; i++) {
                    if (members[i] && String(members[i].id) === String(locked)) { tgt = members[i]; break; }
                }
            }
            if (!tgt && members.length) {
                /* 避開其他敵人已鎖定的目標 */
                var taken = {};
                ((db && db.enemies) || []).forEach(function (o) {
                    if (!o || o === unit || num(o.currentHp, 0) <= 0) return;
                    if (o._lockedTargetId) taken[String(o._lockedTargetId)] = true;
                });
                var free = members.filter(function (m) { return m && m.id && !taken[String(m.id)]; });
                var pool = free.length ? free : members;
                tgt = pool[Math.floor(Math.random() * pool.length)];
                /* 記住，下次不再換 */
                unit._lockedTargetId = tgt && tgt.id ? String(tgt.id) : null;
            }

            var eff = pick ? String(pick.effect || '') : '';
            var isAoe = /aoe|群|掃|範/.test(eff);
            return {
                skillId: pick ? pick.name : '普通攻擊',
                skillName: pick ? String(pick.name) : '普通攻擊',
                kind: 'attack',
                targetName: tgt ? String(tgt.name || '我方') : '—',
                aoe: isAoe,
                splashTeam: isAoe,
                targetIsBoss: false
            };
        }

        /* 我方：主控角色的最強招 */
        var me = charSys.state;
        if (!me) return null;
        var learned = me.skills || {};
        var avail = Object.keys(learned).filter(function (sid) {
            var a = ARTS[sid];
            if (!a) return false;
            if (a.sectReq && a.sectReq !== me.sect) return false;
            return num(me.currentMp, 0) >= num(a.mpCost, 0);
        });
        if (!avail.length) {
            return {
                skillName: '太祖長拳・防身式', kind: 'attack',
                targetName: _delveCurrentTargetName(), aoe: false, targetIsBoss: false
            };
        }
        var best = 'basic_punch', bestP = -1;
        avail.forEach(function (sid) {
            var a = ARTS[sid];
            var lv = num((me.skills || {})[sid], 1);
            var p = num(a.baseMult, 1) + (lv - 1) * 0.14;
            if (num(a.healRatio, 0) > 0) p += 0.5;
            if (p > bestP) { bestP = p; best = sid; }
        });
        var art = ARTS[best] || {};
        var isHeal = num(art.healRatio, 0) > 0 && num(art.baseMult, 0) <= 1.0;
        var curName = _delveCurrentTargetName();
        return {
            skillId: best,
            skillName: String(art.name || best),
            kind: isHeal ? 'heal' : 'attack',
            targetName: isHeal ? String(me.name || '自己') : curName,
            aoe: !!art.isAoe,
            hasHealBonus: num(art.healRatio, 0) > 0 && !isHeal,
            targetIsBoss: false
        };
    }

    /** 取得礦坑當前敵人的名字 */
    function _delveCurrentTargetName() {
        var g = window.HY.game || {};
        var db = g.delveBattle;
        if (!db) return '—';
        var alive = (db.enemies || []).filter(function (e) {
            return e && num(e.currentHp, 0) > 0;
        });
        return alive.length ? String(alive[0].name || '敵人') : '—';
    }

    /** 下一招預告（依戰鬥系統自動選用正確的預測來源）
        @param unit     單位物件
        @param isEnemy  是否敵方
        @param idPrefix DOM id
        @param ctx      可選：{ system:'normal'|'atlas'|'delve' } 強制指定來源 */
    function nextActionHtml(unit, isEnemy, idPrefix, ctx) {
        var info = null;
        var g = window.HY.game || {};
        var sysId = (ctx && ctx.system) || null;

        /* 自動判斷目前是哪個戰鬥系統 */
        if (!sysId) {
            var arb = window.HY.CombatArbiter;
            if (arb && typeof arb.activeSystem === 'function') {
                sysId = arb.activeSystem() || 'normal';
            } else {
                sysId = 'normal';
            }
        }

        try {
            /* ⭐ 礦坑：用自己的資料來源（delveBattle.enemies） */
            if (sysId === 'delve') {
                info = _previewDelveAction(unit, isEnemy);
            }
            /* ⭐ 輿圖：用打圖戰術 */
            else if (sysId === 'atlas') {
                var tac = g.atlasTactics;
                if (tac) {
                    info = isEnemy
                        ? tac.previewEnemyAction(unit, g.partySys.getPartyMembers())
                        : tac.previewAllyAction(unit, g.partySys.getPartyMembers());
                }
            }
            /* 一般戰鬥：uiDexAtb 的預測 */
            if (!info && sysId !== 'delve') {
                var uiDex = window.HY.uiDexAtb;
                if (uiDex && typeof uiDex._previewAction === 'function') {
                    info = uiDex._previewAction(unit, isEnemy);
                }
            }
        } catch (e) { info = null; }

        var htmlId = idPrefix ? ' id="' + idPrefix + '"' : '';
        if (!info) {
            return '<div class="cp-next k-idle"' + htmlId + '>' +
                '<span class="cp-ni">⏳</span><span class="cp-ns">待命</span>' +
                '<span class="cp-na">→</span><span class="cp-nt">—</span></div>';
        }
        var k = info.kind === 'heal' ? 'heal'
            : (info.kind === 'item' ? 'item'
            : (info.kind === 'idle' ? 'idle'
            : (info.kind === 'dead' ? 'dead'
            : (info.kind === 'revive' ? 'revive'
            : (info.kind === 'support' ? 'support' : 'attack')))));
        var ico = info.kind === 'heal' ? '💚'
            : (info.kind === 'item' ? '💊'
            : (info.kind === 'idle' ? '⏳'
            : (info.kind === 'dead' ? '💀'
            : (info.kind === 'revive' ? '✨'
            : (info.kind === 'support' ? '🤝' : (info.targetIsBoss ? '👑' : '⚔️'))))));
        var sk = String(info.skillName || '');
        if (info.hasHealBonus) sk += ' 💚';
        var tgt = info.aoe
            ? (info.splashTeam ? '我方群體' : '敵方群體')
            : (info.targetName || '—');
        return '<div class="cp-next k-' + k + '"' + htmlId + '>' +
            '<span class="cp-ni">' + (info.aoe ? '🌪️' : ico) + '</span>' +
            '<span class="cp-ns">' + esc(sk) + '</span>' +
            '<span class="cp-na">→</span>' +
            '<span class="cp-nt">' + esc(tgt) + '</span></div>';
    }

    /** 完整的單一戰位 HTML
        opts = {
          unit, index, isEnemy, empty, emptyLabel,
          powerText, atbPct, nextId, atbId,
          mainColor, sectLine, statLine, showFeat
        } */
    function unitHtml(opts) {
        var o = opts || {};
        var isEnemy = !!o.isEnemy;
        var idx = num(o.index, 0);

        if (!o.unit || o.empty) {
            var label = o.emptyLabel || '（空缺待命）';
            return '<div class="cp-slot empty' + (isEnemy ? ' enemy' : '') + '">' +
                atbHtml(label, '', 0, isEnemy) +
                barHtml('hp', 0, 0, isEnemy) +
                barHtml('mp', 0, 0, isEnemy) +
                '<div class="cp-line">' + (isEnemy ? '絕技：—' : '[未編入隊員]') + '</div>' +
                '</div>';
        }

        var u = o.unit;
        var isDead = num(u.currentHp, 0) <= 0;
        var cls = 'cp-slot' + (isEnemy ? ' enemy' : '') +
            (isDead ? ' dead' : '') + (o.isMain ? ' main' : '');

        var h = '<div class="' + cls + '" style="border-left-color:' +
            esc(o.mainColor || (isEnemy ? '#ef4444' : '#10b981')) + '">';

        /* ATB + 名字 + 等級 + 戰力 */
        h += atbHtml(o.nameText || String(u.name || '單位'),
            o.powerText || '', o.atbPct, isEnemy, o.atbId, o.levelText || '', o.avatarHtml || '');

        /* HP / MP */
        h += barHtml('hp', u.currentHp, o.maxHp, isEnemy, o.hpId);
        h += barHtml('mp', o.curMp != null ? o.curMp : u.currentMp,
            o.maxMp, isEnemy, o.mpId);

        /* ⭐ v57：能量護盾（有上限才顯示；我方讀 esCurrent，敵方讀 currentEs） */
        var esMax = num(o.maxEs, num(o.energyShield, 0));
        if (!esMax && !isEnemy) esMax = num(u.energyShield, 0);
        if (!esMax && isEnemy) esMax = num(u.energyShield, num(u.maxEs, 0));
        var esCur = (typeof u.esCurrent === 'number') ? u.esCurrent
            : (typeof u.currentEs === 'number') ? u.currentEs
                : esMax;
        h += esBarHtml(esCur, esMax, isEnemy, o.esId);

        /* 下一招預告 */
        h += nextActionHtml(u, isEnemy, o.nextId, o.system ? { system: o.system } : null);

        /* 門派 / 心法行（可選） */
        if (o.sectLine) h += '<div class="cp-line" style="border-left:2px solid #c89d54">' +
            o.sectLine + '</div>';

        /* 門派特色表 */
        if (o.showFeat !== false && !isEnemy) h += featHtml(u);

        /* 屬性行 */
        if (o.statLine) h += '<div class="cp-line" style="border-left:2px solid #10b981">' +
            o.statLine + '</div>';

        h += '</div>';
        return h;
    }

    window.HY.CombatPanel = {
        css: css,
        barHtml: barHtml,
        esBarHtml: esBarHtml,
        atbHtml: atbHtml,
        featHtml: featHtml,
        nextActionHtml: nextActionHtml,
        unitHtml: unitHtml,
        esc: esc,
        num: num,
        fmt: fmt
    };
})();

