                btnZoomIn: root.querySelector('#dv-zoom-in'),
                btnZoomOut: root.querySelector('#dv-zoom-out'),
                btnZoomFit: root.querySelector('#dv-zoom-fit'),
                btnCenter: root.querySelector('#dv-center'),
