            /* 水滴 */
            ctx.beginPath();
            ctx.moveTo(x, y - r * 0.9);
            ctx.bezierCurveTo(x + r * 0.85, y - r * 0.05, x + r * 0.6, y + r * 0.85, x, y + r * 0.85);
            ctx.bezierCurveTo(x - r * 0.6, y + r * 0.85, x - r * 0.85, y - r * 0.05, x, y - r * 0.9);
            ctx.closePath();
