                '.tl-stat{font-size:1.5rem;color:#b8a88a;background:linear-gradient(180deg,#2a1810,#1a0f08);',
                'border:1px solid #5a3a24;border-radius:5px;padding:3px 10px;',
                'box-shadow:inset 0 1px 0 rgba(200,120,80,.16),0 1px 3px rgba(0,0,0,.6);}',
                '.tl-stat b{color:#f0c674;font-variant-numeric:tabular-nums;}',
                '.tl-stat.hl{color:#d8c0a0;background:linear-gradient(180deg,#3a1c12,#1e0e08);',
                'border-color:#7a3a20;}',
                '.tl-stat.hl b{color:#ffb454;}',
                '.tl-stat.warn b{color:#fca5a5;}',
                '.tl-stat.done b{color:#6ee7b7;}',
                /* ⭐ 還有點數可點時，剩餘點數外框緩慢呼吸，提示玩家去配置 */
                '.tl-stat.hl.has{border-color:#c8612a;animation:tl-points-pulse 2.2s ease-in-out infinite;}',
                '@keyframes tl-points-pulse{0%,100%{box-shadow:inset 0 1px 0 rgba(200,120,80,.2),0 0 0 rgba(200,97,42,0);}',
                '50%{box-shadow:inset 0 1px 0 rgba(200,120,80,.2),0 0 11px rgba(200,97,42,.7);}}',
                '.tl-spacer{margin-left:auto;}',
                /* ══════════════════════════════════════════════════════
                   ⭐ POE 風格：搜尋框
                   ══════════════════════════════════════════════════════ */
                '.tl-search-wrap{position:relative;display:inline-flex;align-items:center;',
                'background:linear-gradient(180deg,#1a1408,#0f0b05);',
                'border:1px solid #5a4a28;border-radius:6px;padding:0 6px 0 4px;',
                'box-shadow:inset 0 1px 3px rgba(0,0,0,.9),0 1px 0 rgba(200,164,92,.12);}',
                '.tl-search-ic{font-size:1.5rem;padding:0 4px;opacity:.75;}',
                '.tl-search{background:transparent;border:none;outline:none;color:#f0e0b8;',
