                '.tl-char .cm{color:#64748b;font-size:1.32rem;}',
                '.tl-char .cp{color:#f43f5e;font-size:1.36rem;font-weight:bold;}',
                /* ⭐ POE 風格右側屬性面板（羊皮紙暗金配色） */
                '.tl-side{flex:0 0 330px;overflow-y:auto;',
