// js/canonGongfaData.js  (v2)
// ⭐ 藏書閣・修仙功法：道途屬性（完全取代武學屬性）
//
// ══════════════════════════════════════════════════════════════
// 【為什麼要這支】
//   第一版只是把功法「改名」，效果仍寫 atk / def / crit / pen，
//   跟門派心法在數值上一模一樣 —— 換個名字而已。
//
//   使用者要求：「把名稱效果都改成修仙類，不要跟門派一樣」。
//   所以這裡做兩件事：
//     ① 刪掉功法原本的武學 passive（atk / def / crit / pen …）
//     ② 改用「道途」屬性 —— 門派完全沒有的通道
//
// 【道途屬性】
//     daoHp      道體    額外氣血（純加法，不受裝備百分比影響）
//     daoMp      道元    額外內力
//     daoAtk     道力    額外攻擊
//     daoDef     道基    額外防禦
//     daoRegen   元炁回復  每回合回復氣血 %（修仙續戰，門派沒有）
//     daoBreak   破境     渡劫／突破減傷 %（修仙特有，門派沒有）
//     daoAura    道韻     全元素抗性 %（修仙特有）
//
//   數值刻意對齊原本 passive 的強度，確保移除武學屬性後
//   整體戰力不會掉 —— 只是「換了一套體系」，不是削弱。
// ══════════════════════════════════════════════════════════════
window.HY = window.HY || {};
window.HY.Data = window.HY.Data || {};
(function () {
    'use strict';
    var Data = window.HY.Data;
    if (!Data || !Data.GONGFA) {
        console.error('[canonGongfaData] GONGFA 尚未建立，載入中止');
        return;
    }

    /* ══════════════════════════════════════════════════════
       道途加成表（每部功法「只有」這一組屬性，沒有武學屬性）
       ══════════════════════════════════════════════════════ */
    var DAO = {
        /* ── 黃階 ── */
        gf_yijin:      { daoHp: 120, daoDef: 18, daoRegen: 0.002 },

        /* ── 玄階 ── */
        gf_jiuyang:    { daoAtk: 42, daoBreak: 0.004 },
        gf_xianglong:  { daoAtk: 48, daoDef: 6 },
        gf_taiji:      { daoDef: 46, daoRegen: 0.003 },
        gf_cihang:     { daoHp: 160, daoMp: 45, daoRegen: 0.004 },
        gf_tangmen:    { daoAtk: 40, daoAura: 0.010 },
        gf_taohua:     { daoAtk: 44, daoMp: 12 },
        gf_jingnian:   { daoMp: 80, daoDef: 42, daoAura: 0.010 },
        gf_leiting:    { daoAtk: 46, daoMp: 10 },
        gf_binghuo:    { daoAtk: 44, daoAura: 0.016 },
        gf_yaowang:    { daoHp: 200, daoMp: 40, daoRegen: 0.006 },
        gf_jingmai:    { daoHp: 180, daoDef: 38 },
        gf_changsheng: { daoHp: 260, daoMp: 50, daoRegen: 0.007 },

        /* ── 地階 ── */
        gf_huagong:    { daoAtk: 55, daoMp: 70, daoHp: -30 },
        gf_liumai:     { daoAtk: 62, daoDef: -8 },
        gf_bingpo:     { daoAtk: 52, daoAura: 0.018 },
        gf_beiming:    { daoMp: 130, daoAtk: 48, daoRegen: 0.004 },
        gf_douzhuan:   { daoDef: 58, daoBreak: 0.010 },
        gf_guigu:      { daoAtk: 50, daoMp: 20 },
        gf_jueqing:    { daoAtk: 46, daoDef: 46, daoHp: 140 },
        gf_xixing:     { daoAtk: 58, daoMp: 100, daoHp: -50 },
        gf_ziwei:      { daoMp: 60, daoAura: 0.022, daoBreak: 0.008 },
        gf_wandu:      { daoHp: 240, daoDef: 40, daoAura: 0.014 },
        gf_erengu:     { daoAtk: 64, daoHp: -60 },

        /* ── 天階 ── */
        gf_dugu:       { daoAtk: 75, daoBreak: 0.014 },
        gf_jiuyin:     { daoAtk: 68, daoDef: 52, daoHp: 220, daoRegen: 0.006, daoAura: 0.020 },
        gf_tianmo:     { daoAtk: 92, daoHp: -120, daoBreak: 0.012 },
        gf_wanjian:    { daoAtk: 86, daoDef: -10 }
        /* 註：負值（daoHp / daoDef）是這幾部功法的「道途代價」——
           以命換力、以偏鋒換道體。與門派無關，是修仙取捨。 */
    };

    /* ══════════════════════════════════════════════════════
       套用：掛上道途加成，並移除原本的武學 passive
       ══════════════════════════════════════════════════════ */
    var applied = 0;
    var missing = [];
    Object.keys(Data.GONGFA).forEach(function (id) {
        var gf = Data.GONGFA[id];
        var dao = DAO[id];
        if (!dao) { missing.push(id); return; }
        gf.dao = dao;
        /* ⭐ 關鍵：刪掉武學屬性，避免功法變成「第二套門派心法」 */
        delete gf.passive;
        applied++;
    });

    /* ── 道途文案（UI 用） ── */
    Data.daoEffectText = function (dao) {
        if (!dao) return '';
        var L = Data.DAO_STAT_LABELS || {};
        var out = [];
        ['daoAtk', 'daoDef', 'daoHp', 'daoMp'].forEach(function (k) {
            var v = dao[k];
            if (!v) return;
            out.push((L[k] || k) + (v > 0 ? ' +' : ' ') + v);
        });
        if (dao.daoRegen) out.push((L.daoRegen || '元炁回復') + ' ' + (dao.daoRegen * 100).toFixed(1) + '%／回合');
        if (dao.daoBreak) out.push((L.daoBreak || '破境') + ' ' + (dao.daoBreak * 100).toFixed(1) + '%');
        if (dao.daoAura) out.push((L.daoAura || '道韻') + ' +' + (dao.daoAura * 100).toFixed(1) + '%');
        return out.join('　·　');
    };

    if (missing.length) {
        console.warn('[canonGongfaData] 以下功法未設定道途加成：' + missing.join(', '));
    }
    console.log('[canonGongfaData] ✓ 道途屬性已取代武學屬性（' + applied + ' / ' +
        Object.keys(Data.GONGFA).length + ' 部）');
})();

