/* --- uiStatCodex.js --- */
// js/uiStatCodex.js  (v1)
// ⭐ 屬性圖鑑：把遊戲中所有屬性／能力／效果集中查閱。
//
// 設計目標：
//   ① 一處看完全部屬性 → 不用在戰鬥、天賦、詞綴之間來回猜
//   ② 每條都寫清楚「是什麼 / 怎麼算 / 有什麼用」
//   ③ 支援搜尋（名稱、英文縮寫、說明內容都可搜）
//   ④ 排版分區：分類側欄 + 屬性卡片，卡片用色條區分屬性群組
//
// 對外 API：
//   window.HY.uiStatCodex.open()
//   window.HY.uiStatCodex.close()
//   window.HY.uiStatCodex.toggle()
window.HY = window.HY || {};

(function () {
    var ROOT_ID = 'hy-stat-codex-root';
    var CSS_ID = 'hy-stat-codex-style';
    var ENTRY_ID = 'stat-codex-entry-btn';

    function esc(s) {
        return String(s == null ? '' : s)
            .replace(/&/g, '&amp;').replace(/</g, '&lt;')
            .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    }

    class UIStatCodex {
        constructor(game) {
            this.game = game;
            this._built = false;
            this._activeGroup = 'all';
            this._query = '';
            this.el = {};
        }

        /* ══════════════════════════════════════════════════
           樣式
           ══════════════════════════════════════════════════ */
        _injectStyles() {
            if (document.getElementById(CSS_ID)) return;
            var css = [
                '#hy-stat-codex-root{position:fixed;inset:0;z-index:9500;background:#080b10;',
                'display:flex;flex-direction:column;font-family:"Microsoft JhengHei","PingFang TC",sans-serif;',
                'color:#cbd5e1;}',
                '#hy-stat-codex-root.hidden{display:none!important;}',

                /* ── 頂部 ── */
                '.sc-top{display:flex;align-items:center;gap:14px;padding:10px 18px;',
                'background:linear-gradient(90deg,#12181f,#101a24 55%,#141826);',
                'border-bottom:2px solid #38bdf8;flex:0 0 auto;flex-wrap:wrap;}',
                '.sc-title{font-size:1.06rem;font-weight:bold;color:#7dd3fc;letter-spacing:1px;',
                'display:flex;align-items:center;gap:8px;}',
                '.sc-title .badge{font-size:.66rem;font-weight:normal;color:#0f1720;',
                'background:#38bdf8;border-radius:10px;padding:2px 8px;letter-spacing:0;}',
                '.sc-sub{font-size:.76rem;color:#64748b;}',

                /* ── 搜尋框 ── */
                '.sc-search{flex:1 1 240px;max-width:420px;position:relative;min-width:180px;}',
                '.sc-search input{width:100%;box-sizing:border-box;background:#0d141b;',
                'border:1px solid #24313f;border-radius:6px;color:#e2e8f0;',
                'padding:7px 32px 7px 12px;font-size:.82rem;font-family:inherit;outline:none;',
                'transition:border-color .12s;}',
                '.sc-search input:focus{border-color:#38bdf8;box-shadow:0 0 0 2px rgba(56,189,248,.15);}',
                '.sc-search input::placeholder{color:#4b5563;}',
                '.sc-search .clr{position:absolute;right:8px;top:50%;transform:translateY(-50%);',
                'color:#64748b;cursor:pointer;font-size:.9rem;line-height:1;padding:2px 4px;',
                'border-radius:3px;user-select:none;}',
                '.sc-search .clr:hover{color:#f87171;background:#1a232e;}',

                /* ── 主體：左分類 + 右內容 ── */
                '.sc-main{flex:1 1 auto;display:grid;grid-template-columns:186px minmax(0,1fr);',
                'min-height:0;overflow:hidden;}',
                '.sc-side{background:#0b1017;border-right:1px solid #1a232e;overflow-y:auto;',
                'padding:10px 8px;display:flex;flex-direction:column;gap:3px;}',
                '.sc-gbtn{display:flex;align-items:center;gap:8px;width:100%;box-sizing:border-box;',
                'background:transparent;border:1px solid transparent;border-radius:6px;',
                'color:#94a3b8;padding:8px 10px;font-size:.8rem;cursor:pointer;text-align:left;',
                'font-family:inherit;transition:.12s;position:relative;}',
                '.sc-gbtn .gi{font-size:1rem;line-height:1;flex:0 0 auto;}',
                '.sc-gbtn .gn{flex:1 1 auto;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}',
                '.sc-gbtn .gc{font-size:.68rem;color:#4b5563;font-variant-numeric:tabular-nums;}',
                '.sc-gbtn:hover{background:#111a24;color:#cbd5e1;}',
                '.sc-gbtn.on{background:#0f1c28;border-color:#2a4a63;color:#7dd3fc;font-weight:bold;}',
                '.sc-gbtn.on::before{content:"";position:absolute;left:0;top:6px;bottom:6px;',
                'width:3px;border-radius:2px;background:#38bdf8;}',
                '.sc-gbtn.on .gc{color:#7dd3fc;}',

                '.sc-body{overflow-y:auto;padding:14px 18px 40px;}',

                /* ── 分類區塊標題 ── */
                '.sc-ghead{display:flex;align-items:center;gap:9px;margin:0 0 10px;',
                'padding-bottom:8px;border-bottom:1px solid #1a232e;}',
                '.sc-ghead .gh-ic{font-size:1.15rem;line-height:1;}',
                '.sc-ghead .gh-t{font-size:.95rem;font-weight:bold;}',
                '.sc-ghead .gh-n{font-size:.72rem;color:#4b5563;margin-left:auto;}',
                '.sc-gdesc{font-size:.78rem;color:#7c8ea3;line-height:1.85;margin:-2px 0 14px;',
                'padding:9px 12px;background:#0c131a;border-left:3px solid #24313f;border-radius:0 5px 5px 0;}',
                '.sc-group{margin-bottom:26px;}',

                /* ── 屬性卡片 ── */
                '.sc-card{background:#0e151d;border:1px solid #1e2a36;border-radius:8px;',
                'padding:0;margin-bottom:9px;overflow:hidden;position:relative;transition:.12s;}',
                '.sc-card:hover{border-color:#2c3e50;background:#101822;}',
                '.sc-card>.bar{position:absolute;left:0;top:0;bottom:0;width:3px;}',
                '.sc-card>.in{padding:11px 14px 12px 17px;}',

                '.sc-chd{display:flex;align-items:baseline;gap:9px;flex-wrap:wrap;margin-bottom:6px;}',
                '.sc-cname{font-size:.92rem;font-weight:bold;color:#e2e8f0;}',
                '.sc-cabbr{font-size:.7rem;font-family:Consolas,Monaco,monospace;',
                'color:#64748b;background:#141d27;border:1px solid #24313f;',
                'border-radius:4px;padding:1px 6px;letter-spacing:.3px;}',
                '.sc-cunit{font-size:.7rem;color:#4b5563;margin-left:auto;}',
                '.sc-tags{display:flex;gap:4px;flex-wrap:wrap;margin-left:auto;}',
                '.sc-tag{font-size:.64rem;color:#64748b;background:#111a24;',
                'border:1px solid #1e2a36;border-radius:9px;padding:1px 7px;white-space:nowrap;}',

                '.sc-desc{font-size:.79rem;color:#9fb0c2;line-height:1.85;margin:0 0 8px;}',

                /* 公式區 */
                '.sc-formula{background:#0a1016;border:1px solid #1a2836;border-radius:5px;',
                'padding:7px 11px;font-size:.75rem;font-family:Consolas,Monaco,monospace;',
                'color:#7dd3fc;line-height:1.75;margin-bottom:7px;overflow-x:auto;',
                'white-space:pre-wrap;word-break:break-word;}',
                '.sc-formula .flbl{color:#475569;font-family:"Microsoft JhengHei",sans-serif;',
                'font-size:.7rem;display:block;margin-bottom:2px;letter-spacing:.5px;}',

                /* 備註 */
                '.sc-note{font-size:.73rem;color:#7c8ea3;line-height:1.8;',
                'padding-left:14px;position:relative;}',
                '.sc-note::before{content:"▸";position:absolute;left:2px;color:#4b5563;}',

                /* 空狀態 */
                '.sc-empty{text-align:center;padding:56px 20px;color:#4b5563;font-size:.85rem;line-height:2;}',
                '.sc-empty .ei{font-size:2.4rem;display:block;margin-bottom:12px;opacity:.5;}',

                /* ── 窄螢幕 ── */
                '@media (max-width:820px){',
                '.sc-main{grid-template-columns:1fr;}',
                '.sc-side{flex-direction:row;overflow-x:auto;overflow-y:hidden;',
                'border-right:none;border-bottom:1px solid #1a232e;padding:8px;}',
                '.sc-gbtn{width:auto;flex:0 0 auto;padding:7px 12px;}',
                '.sc-gbtn .gn{display:none;}',
                '.sc-gbtn .gc{display:none;}',
                '.sc-body{padding:12px;}',
                '}'
            ].join('');
            var st = document.createElement('style');
            st.id = CSS_ID;
            st.appendChild(document.createTextNode(css));
            (document.head || document.documentElement).appendChild(st);
        }

        /* ══════════════════════════════════════════════════
           取值
           ══════════════════════════════════════════════════ */
        _groups() {
            var D = (window.HY && window.HY.Data) || {};
            var c = D.STAT_CODEX;
            return (c && c.groups) || [];
        }

        _allStats() {
            var out = [];
            this._groups().forEach(function (g) {
                (g.stats || []).forEach(function (s) {
                    out.push({ stat: s, group: g });
                });
            });
            return out;
        }

        /* ══════════════════════════════════════════════════
           建構
           ══════════════════════════════════════════════════ */
        _build() {
            if (this._built) return;
            this._injectStyles();

            var root = document.createElement('div');
            root.id = ROOT_ID;
            root.className = 'hidden';
            root.innerHTML =
                '<div class="sc-top">' +
                    '<span class="sc-title">📖 屬性圖鑑' +
                        '<span class="badge" id="sc-count">0</span>' +
                    '</span>' +
                    '<span class="sc-sub">遊戲中所有屬性、能力與效果的完整說明</span>' +
                    '<div class="sc-search">' +
                        '<input id="sc-q" type="text" placeholder="搜尋屬性名稱／縮寫／說明…" autocomplete="off">' +
                        '<span class="clr" id="sc-clr" title="清除">✕</span>' +
                    '</div>' +
                    '<button class="sc-btn" id="sc-close" style="background:#182230;color:#cbd5e1;' +
                        'border:1px solid #2e3b4e;border-radius:5px;padding:6px 14px;font-size:.8rem;' +
                        'cursor:pointer;font-family:inherit;">← 返回</button>' +
                '</div>' +
                '<div class="sc-main">' +
                    '<div class="sc-side" id="sc-side"></div>' +
                    '<div class="sc-body" id="sc-body"></div>' +
                '</div>';

            document.body.appendChild(root);
            this.el.root = root;
            this.el.side = root.querySelector('#sc-side');
            this.el.body = root.querySelector('#sc-body');
            this.el.q = root.querySelector('#sc-q');
            this.el.count = root.querySelector('#sc-count');

            var self = this;

            root.querySelector('#sc-close').addEventListener('click', function () { self.close(); });

            this.el.q.addEventListener('input', function () {
                self._query = this.value || '';
                self._renderSide();
                self._renderBody();
            });

            root.querySelector('#sc-clr').addEventListener('click', function () {
                self.el.q.value = '';
                self._query = '';
                self.el.q.focus();
                self._renderSide();
                self._renderBody();
            });

            /* Esc 關閉 */
            this._onKey = function (e) {
                if (e.key === 'Escape' && !root.classList.contains('hidden')) self.close();
            };
            document.addEventListener('keydown', this._onKey);

            /* 委派：點分類 */
            this.el.side.addEventListener('click', function (e) {
                var b = e.target.closest('.sc-gbtn');
                if (!b) return;
                self._activeGroup = b.getAttribute('data-g');
                self._renderSide();
                self._renderBody();
                self.el.body.scrollTop = 0;
            });

            this._built = true;
        }

        /* 是否通過搜尋條件 */
        _match(item) {
            if (!this._query) return true;
            var q = this._query.toLowerCase().trim();
            var s = item.stat, g = item.group;
            var hay = [
                s.name, s.abbr, s.key, s.desc, s.formula, s.note,
                (s.tags || []).join(' '), g.name
            ].join(' ').toLowerCase();
            /* 多關鍵字：全部命中才算 */
            return q.split(/\s+/).every(function (w) { return hay.indexOf(w) !== -1; });
        }

        /* ══════════════════════════════════════════════════
           左側分類
           ══════════════════════════════════════════════════ */
        _renderSide() {
            var groups = this._groups();
            var all = this._allStats();
            var self = this;

            /* 各分類在目前搜尋條件下的命中數 */
            var hit = {};
            all.forEach(function (it) {
                if (!self._match(it)) return;
                hit[it.group.id] = (hit[it.group.id] || 0) + 1;
            });
            var totalHit = Object.keys(hit).reduce(function (a, k) { return a + hit[k]; }, 0);

            var html = '';
            html += '<button class="sc-gbtn' + (this._activeGroup === 'all' ? ' on' : '') +
                '" data-g="all"><span class="gi">🗂️</span><span class="gn">全部屬性</span>' +
                '<span class="gc">' + totalHit + '</span></button>';

            groups.forEach(function (g) {
                var n = hit[g.id] || 0;
                if (self._query && !n) return;   /* 搜尋時隱藏沒有命中的分類 */
                html += '<button class="sc-gbtn' + (self._activeGroup === g.id ? ' on' : '') +
                    '" data-g="' + esc(g.id) + '">' +
                    '<span class="gi">' + esc(g.icon || '•') + '</span>' +
                    '<span class="gn">' + esc(g.name) + '</span>' +
                    '<span class="gc">' + n + '</span></button>';
            });

            this.el.side.innerHTML = html;
            this.el.count.textContent = totalHit + ' 項';
        }

        /* ══════════════════════════════════════════════════
           右側內容
           ══════════════════════════════════════════════════ */
        _cardHtml(item) {
            var s = item.stat, g = item.group;
            var tags = (s.tags || []).map(function (t) {
                return '<span class="sc-tag">' + esc(t) + '</span>';
            }).join('');

            var h = '<div class="sc-card">' +
                '<span class="bar" style="background:' + esc(g.color || '#38bdf8') + ';"></span>' +
                '<div class="in">' +
                    '<div class="sc-chd">' +
                        '<span class="sc-cname">' + esc(s.name) + '</span>' +
                        (s.abbr ? '<span class="sc-cabbr">' + esc(s.abbr) + '</span>' : '') +
                        (s.unit && s.unit !== '—' ?
                            '<span class="sc-cunit">單位：' + esc(s.unit) + '</span>' : '') +
                        (tags ? '<span class="sc-tags">' + tags + '</span>' : '') +
                    '</div>';

            if (s.desc) h += '<div class="sc-desc">' + esc(s.desc) + '</div>';

            if (s.formula) {
                h += '<div class="sc-formula">' +
                    '<span class="flbl">計算方式</span>' + esc(s.formula) + '</div>';
            }

            if (s.note) h += '<div class="sc-note">' + esc(s.note) + '</div>';

            h += '</div></div>';
            return h;
        }

        _renderBody() {
            var groups = this._groups();
            var self = this;
            var only = this._activeGroup;
            var html = '';
            var shown = 0;

            groups.forEach(function (g) {
                if (only !== 'all' && only !== g.id) return;

                var items = (g.stats || []).map(function (s) {
                    return { stat: s, group: g };
                }).filter(function (it) { return self._match(it); });

                if (!items.length) return;
                shown += items.length;

                html += '<div class="sc-group">';
                html += '<div class="sc-ghead">' +
                    '<span class="gh-ic">' + esc(g.icon || '•') + '</span>' +
                    '<span class="gh-t" style="color:' + esc(g.color || '#e2e8f0') + ';">' +
                        esc(g.name) + '</span>' +
                    '<span class="gh-n">' + items.length + ' 項</span>' +
                '</div>';
                if (g.desc) html += '<div class="sc-gdesc">' + esc(g.desc) + '</div>';

                items.forEach(function (it) { html += self._cardHtml(it); });
                html += '</div>';
            });

            if (!shown) {
                html = '<div class="sc-empty">' +
                    '<span class="ei">🔍</span>' +
                    '找不到符合「' + esc(this._query) + '」的屬性<br>' +
                    '<span style="font-size:.76rem;color:#3f4c5a;">試試搜尋「氣血」「暴擊」「抗性」「攻擊」等關鍵字</span>' +
                '</div>';
            }

            this.el.body.innerHTML = html;
        }

        /* ══════════════════════════════════════════════════
           開關
           ══════════════════════════════════════════════════ */
        open() {
            this._build();
            this._renderSide();
            this._renderBody();
            this.el.root.classList.remove('hidden');
            try { this.el.q.focus(); } catch (e) { }
        }

        close() {
            if (this.el.root) this.el.root.classList.add('hidden');
        }

        toggle() {
            if (!this.el.root || this.el.root.classList.contains('hidden')) this.open();
            else this.close();
        }

        /* ══════════════════════════════════════════════════
           工具列按鈕
           ══════════════════════════════════════════════════ */
        injectEntryButton() {
            if (document.getElementById(ENTRY_ID)) return true;
            var self = this;
            var btn = document.createElement('button');
            btn.id = ENTRY_ID;
            btn.className = 'sys-btn';
            btn.style.cssText = 'background:#131c2b;color:#7dd3fc;border:1px solid #2a4a63;' +
                'border-radius:5px;padding:4px 10px;font-size:.78rem;cursor:pointer;margin:0;';
            btn.textContent = '📖 屬性圖鑑';
            btn.title = '查閱遊戲中所有屬性、能力與效果的完整說明';
            btn.addEventListener('click', function () { self.open(); });

            /* ⭐ v70：屬性圖鑑緊接在「武學圖鑑」右側（使用者指定）
               ──────────────────────────────────────────────────────
               做法：找到文字含「武學圖鑑」的按鈕，插在它的 nextSibling。
               找不到時退回工具列尾端（避免整個按鈕消失）。 */
            var poeBtn = null;
            var ctrl = document.querySelector('.system-controls');
            if (ctrl) {
                poeBtn = Array.prototype.filter.call(ctrl.children, function (ch) {
                    return ch && ch.nodeType === 1 && /PoE\s*圖鑑/i.test(String(ch.textContent || ''));
                })[0] || null;
            }
            if (poeBtn && poeBtn.parentNode) {
                poeBtn.parentNode.insertBefore(btn, poeBtn.nextSibling);
                return true;
            }
            /* 退回：工具列尾端 */
            var host = ctrl || document.getElementById('top-bar');
            if (!host) { btn.remove(); return false; }
            host.appendChild(btn);
            return true;
        }
    }

    window.HY.UIStatCodex = UIStatCodex;

    /* ══════════════════════════════════════════════════════
       自動啟動（與其他 UI 模組同一模式）
       ══════════════════════════════════════════════════════ */
    function boot() {
        var game = window.HY.game;
        if (!game) return false;
        if (!window.HY.uiStatCodex) {
            window.HY.uiStatCodex = new UIStatCodex(game);
            window.HY.uiStatCodex.injectEntryButton();
            console.log('[HY StatCodex] ✓ 屬性圖鑑已啟動');
        }
        return true;
    }

    if (document.readyState === 'complete' || document.readyState === 'interactive') {
        setTimeout(boot, 0);
    } else {
        window.addEventListener('DOMContentLoaded', function () { setTimeout(boot, 0); });
    }
    window.addEventListener('load', function () { setTimeout(boot, 130); });

    var tries = 0;
    var timer = setInterval(function () {
        tries += 1;
        if (boot() && window.HY.uiStatCodex) {
            try { window.HY.uiStatCodex.injectEntryButton(); } catch (e) { }
            if (tries > 4) clearInterval(timer);
        }
        if (tries >= 200) clearInterval(timer);
    }, 60);
})();

/* --- statTooltip.js --- */
// js/statTooltip.js  (v1)
// ⭐ 全域屬性提示系統 —— 滑鼠停留 1 秒後顯示說明小窗
//
// ══════════════════════════════════════════════════════════════
// 【設計原則】
//   ① 不侵入既有渲染程式碼
//      各 UI 檔不必改一行，只要在元素上加 data-stat 屬性即可。
//      本檔用「事件委派」監聽整個 document，動態偵測 hover。
//
//   ② 延遲 1 秒才顯示
//      使用者要求「延遲 1 秒」。太短會讓滑過去的元素不斷閃窗，
//      1 秒足以區分「路過」與「真的想查」。
//
//   ③ 單一實例、跟隨滑鼠但不遮擋
//      提示窗固定在 viewport 內，靠近邊緣時自動翻轉方向。
//
//   ④ 資料來源統一
//      一律讀 HY.Data.STAT_CODEX（屬性圖鑑），
//      保證「提示」與「圖鑑」永遠一致，不會兩邊寫不同。
//
// 【怎麼用】
//   方式 A（推薦）：在元素上加屬性
//     <span data-stat="atk">外功攻擊</span>
//     <span data-stat="daoHp">道體 +120</span>     ← 可指定後備說明
//     <span data-stat="elAtk_fire">火 54</span>
//
//   方式 B：用 JS 手動綁定
//     HY.StatTooltip.bind(el, 'crit')
//
//   方式 C：整段文字自動辨識（用於「道途：道基 +18 · 道體 +120」這類）
//     <span data-stat-auto> ... </span>
//     → 會把裡面的每個屬性名稱自動包上 data-stat
// ══════════════════════════════════════════════════════════════
window.HY = window.HY || {};
(function (HY) {
    'use strict';

    var DELAY = 1000;          /* 1 秒（使用者指定） */
    var OFFSET_X = 14;
    var OFFSET_Y = 18;

    var _tipEl = null;
    var _showTimer = null;
    var _curKey = null;        /* 目前顯示中的屬性 key，避免重複重建 */

    /* ══════════════════════════════════════════════════════
       一、建立提示窗 DOM（只建一次）
       ══════════════════════════════════════════════════════ */
    function ensureEl() {
        if (_tipEl && document.body.contains(_tipEl)) return _tipEl;
        _tipEl = document.createElement('div');
        _tipEl.id = 'hy-stat-tooltip';
        _tipEl.style.cssText = [
            'position:fixed',
            'z-index:2147483000',
            'max-width:340px',
            'min-width:200px',
            'padding:9px 12px',
            'background:rgba(11,16,23,0.97)',
            'border:1px solid #3b4a5f',
            'border-radius:6px',
            'box-shadow:0 8px 26px rgba(0,0,0,0.65)',
            'font-size:0.78rem',
            'line-height:1.62',
            'color:#cbd5e1',
            'pointer-events:none',
            'opacity:0',
            'transform:translateY(4px)',
            'transition:opacity .14s ease, transform .14s ease',
            'display:none'
        ].join(';');
        document.body.appendChild(_tipEl);
        return _tipEl;
    }

    /* ══════════════════════════════════════════════════════
       二、資料查詢
       ══════════════════════════════════════════════════════ */

    /** 建立 key → 說明 的索引（第一次用到時才建，之後快取） */
    var _index = null;
    function buildIndex() {
        var D = HY.Data || {};
        var C = D.STAT_CODEX;
        var idx = {};
        if (C && C.groups) {
            C.groups.forEach(function (g) {
                (g.stats || []).forEach(function (s) {
                    if (!s || !s.key) return;
                    idx[s.key] = {
                        name: s.name || s.key,
                        abbr: s.abbr || '',
                        unit: s.unit || '',
                        desc: s.desc || '',
                        formula: s.formula || '',
                        note: s.note || '',
                        tags: s.tags || [],
                        groupName: g.name || '',
                        groupIcon: g.icon || '',
                        groupColor: g.color || '#94a3b8'
                    };
                });
            });
        }
        /* 補上「別名」→ 同一個說明
           （圖鑑用 hpRegen，實際資料用 lifeRegen，兩邊都要能查） */
        var ALIAS = {
            hpRegen: 'lifeRegen',
            mpRegen: 'manaRegen',
            thorns: 'thornsDmg',
            penetration: 'armorPen',
            maxEs: 'esShield',
            blockEffect: 'blockChance',
            leech: 'lifeLeech'
        };
        Object.keys(ALIAS).forEach(function (from) {
            if (idx[from] && !idx[ALIAS[from]]) idx[ALIAS[from]] = idx[from];
            if (idx[ALIAS[from]] && !idx[from]) idx[from] = idx[ALIAS[from]];
        });
        _index = idx;
        return idx;
    }

    function infoOf(key) {
        if (!key) return null;
        var idx = _index || buildIndex();
        return idx[key] || null;
    }

    /* ══════════════════════════════════════════════════════
       三、提示內容組合
       ══════════════════════════════════════════════════════ */
    function esc(s) {
        return String(s == null ? '' : s)
            .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;');
    }

    function buildHtml(key) {
        var info = infoOf(key);
        if (!info || (!info.desc && !info.formula)) return '';

        var color = info.groupColor || '#7dd3fc';
        var h = '';

        /* 標題：圖示 + 名稱 + 單位 */
        h += '<div style="display:flex;align-items:baseline;gap:6px;margin-bottom:5px;' +
            'padding-bottom:5px;border-bottom:1px solid rgba(255,255,255,0.09);">' +
            '<span style="font-size:1rem;line-height:1;">' + esc(info.groupIcon || '📊') + '</span>' +
            '<b style="color:' + color + ';font-size:0.85rem;">' + esc(info.name) + '</b>' +
            (info.unit ? '<span style="color:#64748b;font-size:0.7rem;">（' + esc(info.unit) + '）</span>' : '') +
            '</div>';

        /* 說明 */
        if (info.desc) {
            h += '<div style="color:#cbd5e1;margin-bottom:5px;">' + esc(info.desc) + '</div>';
        }

        /* 計算方式 */
        if (info.formula) {
            h += '<div style="color:#94a3b8;font-size:0.73rem;margin-bottom:5px;">' +
                '<span style="color:#64748b;">計算：</span>' +
                '<span style="color:#a5b4fc;">' + esc(info.formula) + '</span>' +
                '</div>';
        }

        /* 備註 */
        if (info.note) {
            var isWarn = /上限|不會|無法|⚠/.test(info.note);
            h += '<div style="color:' + (isWarn ? '#fcd34d' : '#64748b') + ';font-size:0.72rem;">' +
                '<span style="color:' + (isWarn ? '#fbbf24' : '#52606f') + ';">提示：</span>' +
                esc(info.note) +
                '</div>';
        }

        /* 分類標籤 */
        if (info.groupName) {
            h += '<div style="margin-top:5px;padding-top:4px;border-top:1px solid rgba(255,255,255,0.06);' +
                'color:#475569;font-size:0.68rem;">分類：' + esc(info.groupName) + '</div>';
        }
        return h;
    }

    /* ══════════════════════════════════════════════════════
       四、顯示 / 隱藏
       ══════════════════════════════════════════════════════ */
    function place(x, y) {
        var el = ensureEl();
        el.style.display = 'block';
        /* 先量測尺寸 */
        var w = el.offsetWidth || 280;
        var hgt = el.offsetHeight || 120;
        var vw = window.innerWidth;
        var vh = window.innerHeight;

        var left = x + OFFSET_X;
        var top = y + OFFSET_Y;

        /* 右邊不夠 → 翻到左側 */
        if (left + w > vw - 8) left = Math.max(8, x - w - OFFSET_X);
        /* 下面不夠 → 翻到上方 */
        if (top + hgt > vh - 8) top = Math.max(8, y - hgt - OFFSET_Y);

        el.style.left = left + 'px';
        el.style.top = top + 'px';
    }

    function show(key, x, y) {
        var html = buildHtml(key);
        if (!html) return;
        var el = ensureEl();
        el.innerHTML = html;
        place(x, y);
        /* 觸發 transition */
        requestAnimationFrame(function () {
            el.style.opacity = '1';
            el.style.transform = 'translateY(0)';
        });
        _curKey = key;
    }

    function hide() {
        if (_showTimer) { clearTimeout(_showTimer); _showTimer = null; }
        _curKey = null;
        if (_tipEl) {
            _tipEl.style.opacity = '0';
            _tipEl.style.transform = 'translateY(4px)';
            /* 等 transition 結束再隱藏，避免閃爍 */
            setTimeout(function () {
                if (_tipEl && _tipEl.style.opacity === '0') _tipEl.style.display = 'none';
            }, 160);
        }
    }

    /* ══════════════════════════════════════════════════════
       五、事件委派
       ══════════════════════════════════════════════════════ */

    /** 從事件目標往上找最近的 data-stat */
    function findStatNode(el) {
        var n = el;
        var depth = 0;
        while (n && n !== document.body && depth < 8) {
            if (n.getAttribute) {
                var k = n.getAttribute('data-stat');
                if (k) return { node: n, key: k };
            }
            n = n.parentNode;
            depth++;
        }
        return null;
    }

    var _lastX = 0, _lastY = 0;

    function onMove(e) {
        _lastX = e.clientX;
        _lastY = e.clientY;
        /* 已顯示中 → 跟隨滑鼠（讓它不擋住視線） */
        if (_curKey && _tipEl && _tipEl.style.display === 'block' && _tipEl.style.opacity === '1') {
            place(_lastX, _lastY);
        }
    }

    function onOver(e) {
        var hit = findStatNode(e.target);
        if (!hit) return;
        _lastX = e.clientX;
        _lastY = e.clientY;

        /* 同一個屬性不重複排程 */
        if (_curKey === hit.key) return;
        if (_showTimer) clearTimeout(_showTimer);

        var key = hit.key;
        _showTimer = setTimeout(function () {
            _showTimer = null;
            show(key, _lastX, _lastY);
        }, DELAY);
    }

    function onOut(e) {
        var hit = findStatNode(e.target);
        if (!hit) return;
        /* 移到子元素不算離開 */
        var to = e.relatedTarget;
        if (to && hit.node.contains && hit.node.contains(to)) return;
        hide();
    }

    /* ══════════════════════════════════════════════════════
       六、自動辨識（data-stat-auto）
       ──────────────────────────────────────────────────────────
       用於「道途：道基 +18 · 道體 +120 · 元炁回復 0.2%/回合」
       這類「一長串文字裡混著屬性名」的場合。

       做法：掃描元素文字，把已知屬性名包上 data-stat。
       ⚠ 只在元素初次出現時做一次，避免每幀重掃。
       ══════════════════════════════════════════════════════ */
    var _NAME_TO_KEY = null;
    function buildNameMap() {
        var idx = _index || buildIndex();
        var m = {};
        Object.keys(idx).forEach(function (k) {
            var nm = idx[k].name;
            if (nm && nm.length >= 2) m[nm] = k;
        });
        /* 別名：UI 常用簡稱 → 正式 key */
        var EXTRA = {
            '道體': 'daoHp', '道元': 'daoMp', '道力': 'daoAtk', '道基': 'daoDef',
            '元炁回復': 'daoRegen', '破境': 'daoBreak', '道韻': 'daoAura',
            '外功攻擊': 'atk', '護體防禦': 'def', '最大氣血': 'maxHp', '最大內力': 'maxMp',
            '精準命中': 'hit', '輕功閃避': 'eva', '會心爆擊': 'crit', '會心抵抗': 'critRes',
            '會心傷害': 'critDmg', '會心率加成': 'critFlat', '命中率加成': 'hitFlat',
            '破甲穿透': 'armorPen', '護體加成': 'armorPct', '輕功加成': 'evaPct',
            '格擋率': 'blockChance', '閃避率': 'dodgeChance', '受傷減免': 'dmgReduce',
            /* ⭐ v488：罡氣值／罡氣加成 已移除（機制下架，面板不再顯示） */
            '反震傷害': 'thornsDmg',
            '氣血回復': 'lifeRegen', '內力回復': 'manaRegen',
            '氣血吸取': 'lifeLeech', '內力吸取': 'manaLeech',
            '擊中回血': 'lifeOnHit', '擊中回內': 'manaOnHit', '擊殺回血': 'lifeOnKill',
            '氣血消耗減免': 'hpCostReduce', '內力消耗減免': 'mpCostReduce',
            '出手速度': 'atkSpd', '運功速度': 'castSpd', '身法速度': 'moveSpd',
            '集氣速度': 'atbGain', '冷卻回復': 'cooldownRec',
            '靈獸傷害': 'minionDmg', '靈獸氣血': 'minionHp', '靈獸速度': 'minionSpd',
            '物品稀有度': 'itemRarity', '物品數量': 'itemQuantity', '銀兩獲取': 'goldFind',
            '經驗獲取': 'expGain', '地圖掉落率': 'mapDropRate', '精隨掉落率': 'essenceRate',
            '傷害加成': 'atkPct', '外功傷害': 'physDmg', '九元素內勁': 'elemDmg'
        };
        Object.keys(EXTRA).forEach(function (nm) { m[nm] = EXTRA[nm]; });
        /* 依名稱長度排序，長的先比對（避免「氣血」吃掉「最大氣血」） */
        _NAME_TO_KEY = Object.keys(m)
            .sort(function (a, b) { return b.length - a.length; })
            .map(function (nm) { return { name: nm, key: m[nm] }; });
        return _NAME_TO_KEY;
    }

    function autoTag(root) {
        var list = _NAME_TO_KEY || buildNameMap();
        if (!list.length) return;
        var nodes = root.querySelectorAll ? root.querySelectorAll('[data-stat-auto]') : [];
        Array.prototype.forEach.call(nodes, function (host) {
            if (host.__statTagged) return;
            if (!(host.textContent || '').trim()) return;

            /* ⭐ v467：改為只處理「純文字節點」，不再整個 innerHTML 重寫
               ──────────────────────────────────────────────────────────
               舊做法：取 textContent → 全體轉義 → 正則替換 → 寫回 innerHTML
               問題：宿主內若有 <b>運作：</b> 這種標籤，會被當成純文字轉義，
                    導致標籤消失、粗體變文字。
               新做法：用 TreeWalker 走訪文字節點，只把「屬性名」包成 span，
                    其餘 DOM 結構完全保留。 */
            var walker = document.createTreeWalker(host, NodeFilter.SHOW_TEXT, null, false);
            var textNodes = [];
            var n;
            while ((n = walker.nextNode())) {
                if (n.parentNode && n.parentNode.getAttribute &&
                    n.parentNode.getAttribute('data-stat')) continue;   /* 已標記的跳過 */
                if ((n.nodeValue || '').trim()) textNodes.push(n);
            }

            textNodes.forEach(function (tn) {
                /* 逐個屬性名分段：找出所有命中位置，從後往前插入避免位移 */
                var txt = tn.nodeValue;
                var hits = [];
                list.forEach(function (it) {
                    var idx = txt.indexOf(it.name);
                    while (idx >= 0) {
                        hits.push({ start: idx, end: idx + it.name.length, key: it.key });
                        idx = txt.indexOf(it.name, idx + 1);
                    }
                });
                if (!hits.length) return;
                /* 去除重疊（長名優先，已由 list 排序保證） */
                hits.sort(function (a, b) { return a.start - b.start || (b.end - a.start) - (a.end - a.start); });
                var picked = [];
                var lastEnd = -1;
                hits.forEach(function (h) {
                    if (h.start >= lastEnd) { picked.push(h); lastEnd = h.end; }
                });
                if (!picked.length) return;

                var frag = document.createDocumentFragment();
                var cursor = 0;
                picked.forEach(function (h) {
                    if (h.start > cursor) {
                        frag.appendChild(document.createTextNode(txt.slice(cursor, h.start)));
                    }
                    var sp = document.createElement('span');
                    sp.setAttribute('data-stat', h.key);
                    sp.style.cssText = 'cursor:help;border-bottom:1px dotted rgba(147,197,253,0.45);';
                    sp.textContent = txt.slice(h.start, h.end);
                    frag.appendChild(sp);
                    cursor = h.end;
                });
                if (cursor < txt.length) {
                    frag.appendChild(document.createTextNode(txt.slice(cursor)));
                }
                tn.parentNode.replaceChild(frag, tn);
            });

            host.__statTagged = true;
        });
    }

    /* ══════════════════════════════════════════════════════
       七、安裝
       ══════════════════════════════════════════════════════ */
    function install() {
        if (install.done) return;
        install.done = true;

        document.addEventListener('mouseover', onOver, true);
        document.addEventListener('mouseout', onOut, true);
        document.addEventListener('mousemove', onMove, true);

        /* 捲動時關閉（避免提示窗停在錯位置） */
        window.addEventListener('scroll', hide, true);

        /* 點擊時關閉 */
        document.addEventListener('mousedown', hide, true);

        /* ⭐ 自動辨識：用 MutationObserver 監看新出現的 data-stat-auto
           （只在批次內處理，避免每幀重掃造成卡頓） */
        var pending = null;
        var obs = null;
        try {
            obs = new MutationObserver(function (muts) {
                if (pending) return;
                pending = requestAnimationFrame(function () {
                    pending = null;
                    autoTag(document);
                });
            });
            obs.observe(document.body, { childList: true, subtree: true });
        } catch (e) { }
        /* 首次也掃一次 */
        setTimeout(function () { autoTag(document); }, 400);

        console.log('[StatTooltip] ✓ 屬性提示已安裝（延遲 ' + DELAY + 'ms，' +
            Object.keys(_index || buildIndex()).length + ' 個屬性）');
    }

    /* 對外 API */
    HY.StatTooltip = {
        DELAY: DELAY,
        install: install,
        /** 手動綁定 */
        bind: function (el, key) {
            if (!el || !key) return;
            el.setAttribute('data-stat', key);
            el.style.cursor = 'help';
        },
        /** 手動顯示（除錯用） */
        show: function (key, x, y) { show(key, x || 200, y || 200); },
        hide: hide,
        info: infoOf,
        /** 重新掃描 data-stat-auto */
        refresh: function () { autoTag(document); },
        /** 列出所有可用 key */
        keys: function () { return Object.keys(_index || buildIndex()); }
    };

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', install);
    } else {
        install();
    }
})(window.HY = window.HY || {});

