// js/escortData.js  (v1)
// ⭐ 鏢局護鏢：風險路線任務資料
//
// ══════════════════════════════════════════════════════════════
// 【設計】
//   接鏢單 → 押運（真實時間）→ 途中隨機遭遇劫鏢 → 到貨領賞
//   風險與報酬成正比，可派弟子護鏢（接掌門之路）
//
// 【為什麼接小鎮鏢局】
//   townData 已經有「鏢局」建築但只是收入數字。
//   接上去之後，那個建築才有實際用途。
// ══════════════════════════════════════════════════════════════
window.HY = window.HY || {};
window.HY.Data = window.HY.Data || {};

(function () {
    'use strict';
    var Data = window.HY.Data;

    /* ══════════════════════════════════════════════════════
       一、設定
       ══════════════════════════════════════════════════════ */
    Data.ESCORT_CONFIG = {
        /* 同時可進行的鏢單數 */
        MAX_ACTIVE: 3,
        /* 每張鏢單的基礎押金（依貨值） */
        DEPOSIT_RATE: 0.15,
        /* 劫鏢後損失的貨值比例 */
        LOSS_ON_AMBUSH: 0.45,
        /* 派弟子護鏢可降低的風險 */
        DISCIPLE_RISK_REDUCE: 0.35,
        /* 弟子護鏢時，弟子等級對風險的額外加成 */
        DISCIPLE_LV_BONUS: 0.004
    };

    /* ══════════════════════════════════════════════════════
       二、鏢單等級
       ══════════════════════════════════════════════════════ */
    Data.ESCORT_TIERS = [
        {
            id: 'common', name: '普通貨', icon: '📦', color: '#94a3b8', weight: 45,
            valueBase: 1200, durationMin: 8, risk: 0.10, reqLv: 1,
            desc: '布匹、茶葉之類的日用貨物，劫匪看不上眼。'
        },
        {
            id: 'valuable', name: '貴重貨', icon: '💎', color: '#7dd3fc', weight: 30,
            valueBase: 4500, durationMin: 15, risk: 0.22, reqLv: 20,
            desc: '絲綢、藥材、精鐵，已經值得動手了。'
        },
        {
            id: 'official', name: '官銀', icon: '🏦', color: '#f0c674', weight: 18,
            valueBase: 12000, durationMin: 25, risk: 0.35, reqLv: 45,
            desc: '官府稅銀，沿路都有綠林好漢盯著。'
        },
        {
            id: 'tribute', name: '貢品', icon: '👑', color: '#fbbf24', weight: 7,
            valueBase: 40000, durationMin: 40, risk: 0.52, reqLv: 80,
            desc: '進貢朝廷的珍寶。走這趟，等於把命押上了。'
        }
    ];

    /* ══════════════════════════════════════════════════════
       三、路線
       ══════════════════════════════════════════════════════ */
    Data.ESCORT_ROUTES = [
        {
            id: 'short', name: '官道短途', icon: '🛣️',
            desc: '走驛站官道，有官兵巡邏。安全但利薄。',
            durationMul: 0.6, valueMul: 0.85, riskMul: 0.55,
            flavor: '一路上除了幾個乞丐，什麼都沒遇到。'
        },
        {
            id: 'normal', name: '常規路線', icon: '🗺️',
            desc: '一般商路，風險與報酬都中等。',
            durationMul: 1.0, valueMul: 1.0, riskMul: 1.0,
            flavor: '走了幾天，風景平淡。'
        },
        {
            id: 'secret', name: '暗路', icon: '🌑',
            desc: '不入官冊的山道，速度快、報酬高，但劫匪也多。',
            durationMul: 0.75, valueMul: 1.45, riskMul: 1.7,
            flavor: '山風呼嘯，總覺得暗處有人在看。'
        },
        {
            id: 'water', name: '水路', icon: '⛵',
            desc: '沿江而下，安穩但要繞遠路。',
            durationMul: 1.35, valueMul: 1.15, riskMul: 0.7,
            flavor: '江面平靜，船夫哼著不成調的小曲。'
        }
    ];

    /* ══════════════════════════════════════════════════════
       四、劫鏢事件
       ══════════════════════════════════════════════════════ */
    Data.ESCORT_AMBUSHES = [
        {
            id: 'bandits', name: '山賊劫道', icon: '🗡️', weight: 40,
            desc: '十餘名山賊從林中殺出，攔住去路。',
            /* 需要實際打一場 */
            fight: true, fightMul: 1.0,
            defeatLose: 0.45
        },
        {
            id: 'elite', name: '黑道高手', icon: '👤', weight: 20,
            desc: '一名黑衣高手獨自擋在路中央。',
            fight: true, fightMul: 1.6,
            defeatLose: 0.7
        },
        {
            id: 'toll', name: '索要過路費', icon: '💰', weight: 25,
            desc: '當地惡霸帶著一群人，張口要三成貨值。',
            fight: false, tollRate: 0.30,
            defeatLose: 0
        },
        {
            id: 'storm', name: '暴雨阻路', icon: '⛈️', weight: 15,
            desc: '山洪暴發，車隊被困了兩日。',
            fight: false, tollRate: 0.10, delayMin: 6,
            defeatLose: 0
        }
    ];

    /* ══════════════════════════════════════════════════════
       五、工具
       ══════════════════════════════════════════════════════ */
    function num(v, d) {
        var n = Number(v);
        return isFinite(n) ? n : (typeof d === 'number' ? d : 0);
    }

    Data.escortTier = function (id) {
        var list = Data.ESCORT_TIERS || [];
        for (var i = 0; i < list.length; i++) if (list[i].id === id) return list[i];
        return list[0];
    };

    Data.escortRoute = function (id) {
        var list = Data.ESCORT_ROUTES || [];
        for (var i = 0; i < list.length; i++) if (list[i].id === id) return list[i];
        return list[1];
    };

    /** 依等級可接的鏢單等級 */
    Data.escortAvailableTiers = function (lv) {
        var L = num(lv, 1);
        return (Data.ESCORT_TIERS || []).filter(function (t) { return L >= num(t.reqLv, 1); });
    };

    /**
     * 產生一張鏢單
     * @param {number} lv 玩家等級
     * @param {string} [forceTier]
     */
    Data.makeEscortOrder = function (lv, forceTier) {
        var tiers = Data.escortAvailableTiers(lv);
        if (!tiers.length) tiers = [Data.ESCORT_TIERS[0]];
        var tier = null;
        if (forceTier) {
            tier = Data.escortTier(forceTier);
        } else {
            var total = 0, i;
            for (i = 0; i < tiers.length; i++) total += num(tiers[i].weight, 10);
            var r = Math.random() * total, acc = 0;
            for (i = 0; i < tiers.length; i++) {
                acc += num(tiers[i].weight, 10);
                if (r < acc) { tier = tiers[i]; break; }
            }
            if (!tier) tier = tiers[tiers.length - 1];
        }
        return {
            uid: 'esc_' + Date.now().toString(36) + Math.floor(Math.random() * 1e6).toString(36),
            tierId: tier.id,
            tierName: tier.name,
            tierIcon: tier.icon,
            tierColor: tier.color,
            value: Math.round(num(tier.valueBase, 1000) * (0.85 + Math.random() * 0.3)),
            baseDurationMin: num(tier.durationMin, 10),
            baseRisk: num(tier.risk, 0.1),
            status: 'pending',      /* pending | active | done | failed */
            routeId: null,
            startedAt: 0,
            finishAt: 0,
            ambush: null,
            discipleUid: null,
            reward: 0
        };
    };

    /** 計算實際耗時（毫秒） */
    Data.escortDurationMs = function (order, route) {
        if (!order) return 0;
        var mul = route ? num(route.durationMul, 1) : 1;
        return Math.round(num(order.baseDurationMin, 10) * mul * 60000);
    };

    /** 計算實際風險（0~1） */
    Data.escortRisk = function (order, route, discipleLv, hasDisciple) {
        if (!order) return 0;
        var r = num(order.baseRisk, 0.1);
        if (route) r *= num(route.riskMul, 1);
        if (hasDisciple) {
            var cfg = Data.ESCORT_CONFIG || {};
            r *= (1 - num(cfg.DISCIPLE_RISK_REDUCE, 0.35));
            r *= Math.max(0.4, 1 - num(discipleLv, 1) * num(cfg.DISCIPLE_LV_BONUS, 0.004));
        }
        return Math.max(0.02, Math.min(0.95, r));
    };

    /** 計算報酬 */
    Data.escortReward = function (order, route) {
        if (!order) return 0;
        var v = num(order.value, 0);
        var mul = route ? num(route.valueMul, 1) : 1;
        return Math.round(v * mul);
    };

    /** 抽一個劫鏢事件 */
    Data.rollAmbush = function () {
        var list = Data.ESCORT_AMBUSHES || [];
        var total = 0, i;
        for (i = 0; i < list.length; i++) total += num(list[i].weight, 10);
        var r = Math.random() * total, acc = 0;
        for (i = 0; i < list.length; i++) {
            acc += num(list[i].weight, 10);
            if (r < acc) return list[i];
        }
        return list[0];
    };

    if (window.console && console.log) {
        console.log('[HY Escort] 已載入 ' + Data.ESCORT_TIERS.length + ' 種鏢單 / ' +
            Data.ESCORT_ROUTES.length + ' 條路線 / ' +
            Data.ESCORT_AMBUSHES.length + ' 種劫鏢事件');
    }
})();

