                /* ⭐ v560：仙界七重清單 */
                '.cult-soon-list{display:flex;flex-direction:column;gap:5px;}',
                '.cult-soon-list .cult-soon{padding:8px 11px;}',
                '.cult-soon-list .cult-soon .ic{font-size:1.5rem;}',
                '.cult-soon-list .cult-soon .t{font-size:.82rem;}',
                '.cult-soon-list .cult-soon .d{font-size:.7rem;margin-top:3px;}',
                '.cult-soon-list .cult-soon .f{font-size:.66rem;margin-top:2px;}',
                '.realm-ic{font-size:2.6rem;line-height:1;}',
                '.realm-nm{font-size:1.4rem;font-weight:bold;}',
                '.realm-lv{font-size:.8rem;color:#64748b;margin-top:2px;}',
                '.realm-bar{flex:1 1 200px;min-width:140px;}',
                '.cult-bar{height:8px;background:#0a0f16;border-radius:4px;overflow:hidden;}',
