                '.mer-pt:last-child{border-bottom:none;}',
                '.mer-pt.opened{background:#0d1a14;}',
                '.mer-pt.can .dot{box-shadow:0 0 8px currentColor;}',
                '.mer-dot{width:11px;height:11px;border-radius:50%;border:2px solid #2b3a4b;',
                'flex:0 0 auto;background:#0a1018;}',
                '.mer-pt.opened .mer-dot{background:#6ee7b7;border-color:#6ee7b7;}',
                '.mer-pt.can .mer-dot{border-color:#38bdf8;}',
                '.mer-conn{width:2px;height:8px;background:#253244;margin-left:9px;}',
                '.mer-pt .nm{font-weight:bold;color:#cbd5e1;min-width:52px;}',
                '.mer-pt .bn{color:#6ee7b7;font-size:.7rem;flex:1 1 auto;}',
