                /* 陣盤 */
                '.fg-wrap{display:flex;gap:16px;flex-wrap:wrap;align-items:flex-start;}',
                /* ⭐ v666：3 欄九宮格，欄標題放在上方（不旋轉） */
                '.fg-board{display:flex;flex-direction:column;gap:6px;',
